<?php
/**
 * Streams a private report attachment through PHP rather than serving the
 * uploads/ URL directly. Two paths:
 *   - signed URL  (`exp`+`sig`) — valid 60s, generated by the REST endpoint
 *   - bearer header — falls back if signed URL not provided
 *
 * Either way, the request must establish that the caller's portal session
 * is for the same order_id as the report being requested.
 */

namespace WpDreamers\WPDDBP\Controllers\PatientPortal;

use WpDreamers\WPDDBP\Controllers\TestOrder\Model\TestReport;

defined( 'ABSPATH' ) || exit;

class Download {

	const SIG_TTL = 60;

	public static function signed_url( $report_id, $disposition = 'inline' ) {
		$exp = time() + self::SIG_TTL;
		$sig = self::sign( (int) $report_id, $exp, $disposition );
		return rest_url( sprintf( 'wpddb_pro/v1/patient-portal/reports/%d/%s', (int) $report_id, $disposition === 'attachment' ? 'download' : 'view' ) )
			. '?exp=' . $exp . '&sig=' . $sig;
	}

	public static function verify_signature( $report_id, $exp, $sig, $disposition ) {
		if ( ! $exp || ! $sig || (int) $exp < time() ) return false;
		return hash_equals( self::sign( (int) $report_id, (int) $exp, $disposition ), (string) $sig );
	}

	private static function sign( $report_id, $exp, $disposition ) {
		$secret = defined( 'SECURE_AUTH_KEY' ) ? SECURE_AUTH_KEY : wp_salt( 'auth' );
		return substr( hash_hmac( 'sha256', $report_id . '|' . $exp . '|' . $disposition, $secret ), 0, 32 );
	}

	public static function stream( $report_id, $disposition = 'inline' ) {
		$report = TestReport::find( (int) $report_id );
		if ( ! $report ) {
			status_header( 404 );
			exit;
		}
		$file = get_attached_file( (int) $report['attachment_id'] );
		if ( ! $file || ! file_exists( $file ) ) {
			status_header( 404 );
			exit;
		}
		$filename = basename( $file );
		nocache_headers();
		header( 'Content-Type: application/pdf' );
		header( 'Content-Length: ' . filesize( $file ) );
		header( 'Content-Disposition: ' . ( $disposition === 'attachment' ? 'attachment' : 'inline' ) . '; filename="' . $filename . '"' );
		readfile( $file );
		exit;
	}
}
